// acosf(v . (0, 0, 1)) * 180/pi (the reference axis 0x6836D0 copied to sp+0x50; the dot product through ACC in the
// compiled order y, x, z), negated when v.x < 0, plus 180 -> 0..360. Inside: with half = fov / 2,
//   h + half <= 360 and h - half >= 0:  h - half <= d <= h + half;
//   h + half <= 360 and h - half <  0:  d <= h + half, or d >= h - half + 360;
//   h + half >  360:                    d >= h - half, or d <= h + half - 360.
