    charge(ctx, 21);
    v0 = 0x43340000;  // 180.0
    mtc1(v0, f0);
    add_s(f23, f23, f0);
    lwc1(f3, sp, 0x68);
    lwc1(f2, sp, 0x60);
    lwc1(f1, sp, 0x50);
    lwc1(f0, sp, 0x64);
    mula_s(f0, f21);
    madda_s(f2, f1);
    madd_s(f12, f3, f20);
    jal(ctx, 0x1C6334u, gen::fn_acosf_0052e9e8);
    lwc1(f1, gp, kGpRadToDeg);  // 0x7CAFA0
    mul_s(f2, f1, f0);
    lwc1(f1, sp, 0x60);
    mtc1(zero, f0);
    c_lt_s(f1, f0);
