        lwc1(f1, s1, 4);
        lwc1(f0, s1, 8);
        swc1(f2, sp, 0x5C);
        swc1(f1, sp, 0x60);
        swc1(f0, sp, 0x64);
        lwc1(f0, sp, 0x54);
