        mtc1(v0, f1);
        add_s(f0, f0, f1);
        swc1(f0, sp, 0x54);
        lwc1(f0, sp, 0x60);
        add_s(f0, f0, f1);
        swc1(f0, sp, 0x60);
        a1 = addiu(sp, 0x70);
        jal(ctx, 0x1C6530u, gen::fn_sub_1ACC30_001acc30);
